        parts = []
        for c in content:
            if isinstance(c, dict):
                t = c.get('type','')
                if t == 'text':
                    parts.append(c.get('text','')[:300])
                elif t == 'tool_use':
                    parts.append(f\"[tool_use: {c.get('name','')}]\")
                elif t == 'tool_result':
                    r = c.get('content','')
