                        r = ' '.join(x.get('text','')[:150] for x in r if isinstance(x,dict))
                    parts.append(f\"[tool_result: {str(r)[:150]}]\")
                else:
                    parts.append(f'[{t}]')
        content = ' | '.join(parts)
    elif isinstance(content, str):
        content = content[:400]
    else:
        content = str(content)[:400]
    print(f'--- {role} ---')
    print(content[:500])
    print()
